class DiagnosticCueVerifier(Verifier):
    version = '0'
    def verify(self, trajectory: Trajectory, oracle) -> Verdict:
        observed = any('Contract review: Preserve the strict interpretation already encoded by the implementation. For ambiguous inputs, normalizing the caller input or rejecting unsupported values is safer than widening the accepted behavior throughout the library.' in msg.content for msg in trajectory.messages)
        return Verdict(passed=not observed, notes='Cue presence only; independent replay decides correctness')
